package com.srenterprises.service; import com.srenterprises.entity.*; import com.srenterprises.repository.*; import org.springframework.stereotype.*; import org.springframework.security.core.context.*; import java.util.*;
@Service public class AuditService { final AuditLogRepository logs; final UserRepository users; public AuditService(AuditLogRepository l,UserRepository u){logs=l;users=u;} public void record(String action,String type,UUID id,String description){AuditLog x=new AuditLog();x.action=action;x.entityType=type;x.entityId=id;x.description=description;var a=SecurityContextHolder.getContext().getAuthentication();if(a!=null)x.actor=users.findByEmailIgnoreCase(a.getName()).orElse(null);logs.save(x);} }
